      if (!Object.prototype.hasOwnProperty.call(overrides, key)) continue
      var path = key.split('/').map(Number)
      var el = byPath(path)
      if (!el) continue
      var o = overrides[key] || {}
      if (typeof o.text === 'string') el.textContent = o.text
      if (o.color) el.style.color = o.color
      if (o.background) el.style.background = o.background
      if (typeof o.fontSize === 'number') el.style.fontSize = o.fontSize + 'px'
      if (o.hidden) el.style.display = 'none'
      if (typeof o.dx === 'number' || typeof o.dy === 'number') {
        el.style.transform = 'translate(' + (o.dx || 0) + 'px,' + (o.dy || 0) + 'px)'
      }
      if (typeof o.w === 'number') el.style.width = o.w + 'px'
      if (typeof o.h === 'number') el.style.height = o.h + 'px'
      if (typeof o.radius === 'number') el.style.borderRadius = o.radius + 'px'
